 string T(string text){int column=language=="es"?1:language=="en"?2:0;if(column==0)return text;foreach(var row in Translations)if(row[0]==text)return row[column];return text;}
 void ApplyLanguage(){foreach(Control control in Controls){if((string)control.Tag=="config")control.Text=T("Configuração");if((string)control.Tag=="exit")control.Text=T("Sair");}hold.Text=T(peak.Hold?"Pico OFF":"Pico ON");if(aboutWindow!=null&&!aboutWindow.IsDisposed){aboutWindow.Text=T("Sobre o Flex Meter");foreach(Control c in aboutWindow.Controls){string tag=c.Tag as string;if(tag=="@version")c.Text=T("Versão ")+AppVersion;else if(tag=="@about")c.Text=T("Medidor de sinal para FlexRadio, com leitura contínua e retenção de pico.")+"\n\n"+T("Ligação por rede local ou SmartSDR CAT.")+"\n\n"+T("Desenvolvido por Eduardo Arraia - CT7ASY")+"\n\n"+T("Software de distribuição gratuita.");else if(tag!=null)c.Text=T(tag);}}if(sharpBuffer!=null){sharpBuffer.Dispose();sharpBuffer=null;}Invalidate();}
 void SaveLanguage(string next){if(next!="pt"&&next!="es"&&next!="en")throw new ArgumentException("language");var lines=new List<string>();if(File.Exists(SettingsPath))foreach(string line in File.ReadAllLines(SettingsPath))if(!line.StartsWith("language="))lines.Add(line);lines.Add("language="+next);Directory.CreateDirectory(Path.GetDirectoryName(SettingsPath));File.WriteAllLines(SettingsPath,lines.ToArray());language=next;ApplyLanguage();}

 public class UpdatePackage {public string Tag,Name,Digest,Notes;public long Size;}
 public static UpdatePackage ReadUpdatePackage(string json){var data=new JavaScriptSerializer{MaxJsonLength=1048576}.Deserialize<Dictionary<string,object>>(json);Version latest=PublishedVersion(json);if(latest==null)return null;string tag=(string)data["tag_name"];object raw;if(!data.TryGetValue("assets",out raw)||!(raw is System.Collections.IEnumerable))throw new IOException("Missing assets");UpdatePackage found=null;string expected="Instalar-Flex-Meter-"+tag.TrimStart('v')+".exe";
  foreach(object item in (System.Collections.IEnumerable)raw){var asset=item as Dictionary<string,object>;if(asset==null||!asset.ContainsKey("name")||(string)asset["name"]!=expected)continue;if(found!=null)throw new IOException("Ambiguous installer");long size;object digest,bytes;if(!asset.TryGetValue("digest",out digest)||!(digest is string)||!Regex.IsMatch((string)digest,@"^sha256:[a-f0-9]{64}$")||!asset.TryGetValue("size",out bytes)||!long.TryParse(Convert.ToString(bytes),out size)||size<=0||size>64000000)throw new IOException("Invalid integrity metadata");found=new UpdatePackage{Tag=tag,Name=expected,Digest=(string)digest,Size=size,Notes=data.ContainsKey("body")?Convert.ToString(data["body"]):""};}if(found==null)throw new IOException("Missing installer");return found;
 }
 static string FileDigest(string path){using(var sha=SHA256.Create())using(var stream=File.OpenRead(path))return "sha256:"+BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
 public static bool VerifyInstaller(string path,UpdatePackage package){return new FileInfo(path).Length==package.Size&&FileDigest(path)==package.Digest;}
 string GetReleaseJson(){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create("https://api.github.com/repos/CT7ASY/FlexMeter/releases/latest");request.UserAgent="FlexMeter/"+AppVersion;request.Accept="application/vnd.github+json";request.Timeout=8000;request.ReadWriteTimeout=8000;request.AutomaticDecompression=DecompressionMethods.GZip|DecompressionMethods.Deflate;using(var response=(HttpWebResponse)request.GetResponse())using(var reader=new StreamReader(response.GetResponseStream())){var text=new System.Text.StringBuilder();var buffer=new char[4096];int n;while((n=reader.Read(buffer,0,buffer.Length))>0){text.Append(buffer,0,n);if(text.Length>1048576)throw new IOException("Response too large");}return text.ToString();}}
 async Task CheckForUpdates(bool manual,Form owner){if(updateCheckRunning||closing)return;updateCheckRunning=true;try{string json=await Task.Run((Func<string>)GetReleaseJson);if(closing||owner.IsDisposed)return;Version latest=PublishedVersion(json);if(latest==null)throw new IOException("Invalid release");if(latest>ParseReleaseVersion(AppVersion)){var package=ReadUpdatePackage(json);ShowUpdate(package,owner);}else if(manual)MessageBox.Show(owner,T("O Flex Meter está atualizado.")+"\n"+T("Versão instalada: ")+AppVersion,T("Atualizações"),MessageBoxButtons.OK,MessageBoxIcon.Information);
  }catch(WebException ex){if(manual&&!closing&&!owner.IsDisposed){var response=ex.Response as HttpWebResponse;MessageBox.Show(owner,T(response!=null&&response.StatusCode==HttpStatusCode.NotFound?"Ainda não existe uma versão publicada no GitHub.":"Não foi possível verificar atualizações. Verifica a ligação à Internet e tenta novamente."),T("Atualizações"),MessageBoxButtons.OK,MessageBoxIcon.Information);}}
  catch(Exception){if(manual&&!closing&&!owner.IsDisposed)MessageBox.Show(owner,T("Não foi possível verificar atualizações. Verifica a ligação à Internet e tenta novamente."),T("Atualizações"),MessageBoxButtons.OK,MessageBoxIcon.Information);}finally{updateCheckRunning=false;}}
 async Task<string> DownloadInstaller(UpdatePackage package,IProgress<int> progress,CancellationToken token){string folder=Path.Combine(Path.GetTempPath(),"FlexMeter-update-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string target=Path.Combine(folder,package.Name);try{await Task.Run(delegate{ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create("https://github.com/CT7ASY/FlexMeter/releases/download/"+Uri.EscapeDataString(package.Tag)+"/"+Uri.EscapeDataString(package.Name));request.UserAgent="FlexMeter/"+AppVersion;request.Timeout=30000;request.ReadWriteTimeout=30000;using(token.Register(delegate{request.Abort();}))using(var response=request.GetResponse())using(var input=response.GetResponseStream())using(var output=new FileStream(target,FileMode.CreateNew,FileAccess.Write,FileShare.None)){long received=0;var buffer=new byte[65536];int n;while((n=input.Read(buffer,0,buffer.Length))>0){token.ThrowIfCancellationRequested();received+=n;if(received>package.Size)throw new IOException("Size mismatch");output.Write(buffer,0,n);progress.Report((int)(received*100/package.Size));}if(received!=package.Size)throw new IOException("Incomplete download");}token.ThrowIfCancellationRequested();if(!VerifyInstaller(target,package))throw new IOException("Digest mismatch");},token);return target;}catch{try{File.Delete(target);Directory.Delete(folder);}catch(IOException){}throw;}}
 void ShowUpdate(UpdatePackage package,Form owner){using(var dialog=new MovableDialog())using(var cancelDownload=new CancellationTokenSource()){dialog.Text=T("Atualizações");dialog.FormBorderStyle=FormBorderStyle.None;dialog.ClientSize=new Size(480,370);dialog.Font=new Font("Arial",10);dialog.BackColor=Color.FromArgb(7,31,52);dialog.ForeColor=Color.WhiteSmoke;
