  action.Click+=async delegate{if(downloading)return;if(prepared!=null){if(MessageBox.Show(dialog,T("O Flex Meter vai fechar para instalar a atualização. Continuar?"),T("Atualizações"),MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;try{if(!VerifyInstaller(prepared,package))throw new IOException("Digest mismatch");Process.Start(new ProcessStartInfo(prepared){UseShellExecute=true});handedOff=true;dialog.Close();Application.Exit();}catch(Exception){MessageBox.Show(dialog,T("Não foi possível iniciar o instalador. Tenta descarregar novamente."),T("Atualizações"));try{File.Delete(prepared);}catch(IOException){}prepared=null;action.Text=T("Descarregar atualização");progress.Value=0;}return;}
   downloading=true;action.Enabled=false;status.Text=T("A descarregar…");var reporter=new Progress<int>(delegate(int value){if(!dialog.IsDisposed){progress.Value=value;status.Text=T("A descarregar…")+" "+value+"%";}});try{prepared=await DownloadInstaller(package,reporter,cancelDownload.Token);if(dialog.IsDisposed){try{File.Delete(prepared);}catch(IOException){}return;}status.Text=T("Download verificado. Pronto para instalar.");action.Text=T("Instalar atualização");}catch(Exception){if(!cancelDownload.IsCancellationRequested&&!dialog.IsDisposed){status.Text=T("Não foi possível descarregar ou verificar o instalador. Tenta novamente.");progress.Value=0;}}finally{downloading=false;if(!action.IsDisposed)action.Enabled=true;}};
  dialog.FormClosing+=delegate{cancelDownload.Cancel();};dialog.Controls.AddRange(new Control[]{title,versions,notes,status,progress,action,close});dialog.CancelButton=close;ShowWithoutOverlap(dialog,owner);if(!handedOff&&prepared!=null)try{File.Delete(prepared);Directory.Delete(Path.GetDirectoryName(prepared));}catch(IOException){}
